-- ════════════ 0003_store_assignment.sql ════════════
-- Nearest-store assignment, with Cody able to change it after the order is placed.

alter table stores    add column latitude double precision, add column longitude double precision;
alter table addresses add column latitude double precision, add column longitude double precision;

-- Each order gets one store per chain. Set automatically to the nearest at checkout.
alter table orders
  add column kroger_store_id uuid references stores,
  add column meijer_store_id uuid references stores,
  add column store_reassigned_at timestamptz;   -- set when Cody changes it by hand

-- Guard: the Kroger slot must point at a Kroger store, and the Meijer slot at a Meijer.
create function check_order_stores() returns trigger language plpgsql as $$
begin
  if new.kroger_store_id is not null and (select chain from stores where id = new.kroger_store_id) <> 'kroger' then
    raise exception 'kroger_store_id must be a Kroger store';
  end if;
  if new.meijer_store_id is not null and (select chain from stores where id = new.meijer_store_id) <> 'meijer' then
    raise exception 'meijer_store_id must be a Meijer store';
  end if;
  if tg_op = 'UPDATE' and (new.kroger_store_id is distinct from old.kroger_store_id
                        or new.meijer_store_id is distinct from old.meijer_store_id) then
    new.store_reassigned_at := now();
  end if;
  return new;
end $$;
create trigger orders_check_stores before insert or update on orders
  for each row execute function check_order_stores();

-- ════════════ 0004_signup_phone.sql ════════════
-- Save the phone number entered at sign-up (it arrives with the account, before email confirmation).
create or replace function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into profiles (id, full_name, phone)
  values (new.id, new.raw_user_meta_data->>'full_name', nullif(new.raw_user_meta_data->>'phone', ''));
  return new;
end $$;

-- ════════════ 0005_second_store_fee.sql ════════════
-- Orders are meant to be one store. Adding the other store costs a flat extra fee.
alter table settings add column second_store_fee_cents integer not null default 500;
alter table orders   add column second_store_fee_cents integer not null default 0;

-- ════════════ 0006_second_store_rule.sql ════════════
-- Can an order that STARTS at this store add items from the other chain?
-- Greencastle Kroger: no (no Meijer nearby). Every other store: yes.
alter table stores add column allow_second_store boolean not null default true;
update stores set allow_second_store = false where chain = 'kroger' and name like '%Greencastle%';

-- ════════════ 0007_second_store_fee_10.sql ════════════
-- Second-store fee placeholder: $10.
alter table settings alter column second_store_fee_cents set default 1000;
update settings set second_store_fee_cents = 1000;

-- ════════════ 0008_meijer_live.sql ════════════
-- Meijer prices come from a default store and can be ~20% off Cody's stores.
-- Hold this much EXTRA on the card for Meijer items (on top of auth_buffer_pct).
alter table settings add column meijer_extra_buffer_pct smallint not null default 10;

-- ════════════ 0009_shopping_mode.sql ════════════
-- Shopping mode, per-item substitutions, per-store aisles, 2-hour windows.

-- ── Per-item substitutions ──
create type item_sub_choice as enum ('approved', 'codys_pick', 'store_brand', 'refund', 'other');
alter table order_items
  add column sub_choice item_sub_choice not null default 'codys_pick',
  add column scanned_upc text,                    -- what Cody scanned in the store
  add column added_by_shopper boolean not null default false,
  add column removed boolean not null default false,
  add column found_quantity numeric(8,2);         -- how many Cody actually got

-- ── Where each product sits in each store ──
-- Kroger: filled from Kroger's API. Meijer: filled in by Cody while shopping.
create table product_locations (
  store_id    uuid not null references stores on delete cascade,
  product_id  uuid not null references products on delete cascade,
  aisle       text not null,         -- "Aisle 8", "Dairy", "Produce"
  sort_key    integer,               -- for ordering the walk through the store
  source      text not null default 'cody' check (source in ('kroger', 'cody')),
  updated_at  timestamptz not null default now(),
  primary key (store_id, product_id)
);
alter table product_locations enable row level security;
create policy product_locations_admin on product_locations for all using (is_admin()) with check (is_admin());

-- ── Shopping batches (several orders shopped together) ──
create table shopping_batches (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  finished_at timestamptz
);
alter table orders add column batch_id uuid references shopping_batches on delete set null;
alter table shopping_batches enable row level security;
create policy batches_admin on shopping_batches for all using (is_admin()) with check (is_admin());

-- ── 2-hour delivery windows (replaces Morning / Afternoon; old ones kept for past orders) ──
update slot_templates set active = false;
insert into slot_templates (label, start_time, end_time, capacity, sort_order) values
  ('10am–12pm', '10:00', '12:00', 3, 1),
  ('12–2pm',    '12:00', '14:00', 3, 2),
  ('2–4pm',     '14:00', '16:00', 3, 3),
  ('4–6pm',     '16:00', '18:00', 3, 4);

-- Aisle for typed-in requests (no catalog product to attach it to).
alter table order_items add column shopper_aisle text;

-- ════════════ 0010_shelf_detail.sql ════════════
-- Finer location inside an aisle (Kroger sometimes sends bay/shelf/side; Cody can type it too).
alter table product_locations
  add column bay integer,        -- position along the aisle, for walking order
  add column detail text;        -- "Left side · Bay 4 · Shelf 3"

-- ════════════ 0011_meijer_aisles.sql ════════════
-- Meijer store numbers (from the meijer-selected-store cookie) and Meijer-sourced aisle data.
update stores set external_location_id = '338' where chain = 'meijer' and name like '%Brownsburg%';
-- Avon: fill in once known, e.g.  update stores set external_location_id = '###' where chain='meijer' and name like '%Avon%';

alter table product_locations drop constraint if exists product_locations_source_check;
alter table product_locations add constraint product_locations_source_check check (source in ('kroger', 'meijer', 'cody'));

-- ════════════ 0012_subs_available_receipts.sql ════════════
-- 1) Specific products the customer approved as substitutes: [{ name, externalId, upc, priceCents }]
alter table order_items add column approved_subs jsonb not null default '[]';

-- 2) "Available now": Cody is out and can take same-day (ASAP) orders until this time.
alter table settings
  add column available_until timestamptz,
  add column asap_capacity smallint not null default 2;   -- open ASAP orders at once
alter table orders
  add column asap boolean not null default false,
  alter column slot_template_id drop not null;            -- ASAP orders have no 2-hour window

-- 3) Receipt totals, per store, entered after shopping.
alter table orders
  add column receipt_kroger_cents integer,
  add column receipt_meijer_cents integer,
  add column finalized_at timestamptz;

-- ════════════ 0013_payments.sql ════════════
-- Card payments (Stripe).
alter table profiles add column stripe_customer_id text;

alter table orders
  add column payment_status text not null default 'none'
    check (payment_status in ('none', 'card_saved', 'authorized', 'captured', 'failed', 'canceled')),
  add column stripe_payment_method_id text,
  add column payment_error text,
  add column authorized_at timestamptz,
  add column captured_cents integer,
  add column extra_charge_payment_intent_id text,
  add column refunded_cents integer not null default 0;

-- ════════════ 0014_stripe_webhooks.sql ════════════
-- Stripe webhooks: remember which events were handled, and track disputes.
create table stripe_events (
  id text primary key,            -- Stripe's event id (evt_...)
  type text not null,
  received_at timestamptz not null default now()
);
-- Only the server (service role) touches this table; no policies means the public key can't.
alter table stripe_events enable row level security;

alter table orders add column dispute_status text;   -- null, 'open', 'won', 'lost', ...

-- Webhooks look orders up by their payment intents.
create index orders_stripe_payment_intent_idx on orders (stripe_payment_intent_id);
create index orders_extra_charge_payment_intent_idx on orders (extra_charge_payment_intent_id);

-- ════════════ 0015_fees_welcome_tips.sql ════════════
-- 1) New service fee tiers (by number of unique items).
--    Orders already placed keep the fee they were quoted; this only affects new orders.
delete from fee_tiers;
insert into fee_tiers (min_items, max_items, fee_cents, label) values
  (1,  10,   1500, 'Quick Trip'),
  (11, 25,   3000, 'Regular Run'),
  (26, 40,   4000, 'Big Shop'),
  (41, 60,   5000, 'Stock-Up'),
  (61, null, 6000, 'Full Haul');

-- 2) The fee breakdown screen shown once after creating an account.
alter table profiles add column fees_seen_at timestamptz;

-- 3) Tips added after delivery (a separate charge on the saved card).
alter table orders
  add column later_tip_cents integer not null default 0,
  add column later_tip_payment_intent_id text,
  add column later_tip_at timestamptz;
create index orders_later_tip_payment_intent_idx on orders (later_tip_payment_intent_id);

-- 4) Security fix: customers could previously edit ANY column of their own profile from the browser,
--    including `role` (making themselves admin) and `stripe_customer_id`. Now they can only change
--    their name, phone, and the "seen the fees" flag. Profiles are created by the sign-up trigger,
--    and the server (service role) is unaffected.
revoke insert, update, delete on profiles from anon, authenticated;
grant update (full_name, phone, fees_seen_at) on profiles to authenticated;

-- ════════════ 0016_item_refunds_and_grants.sql ════════════
-- 1) Item refunds (missing / damaged / wrong items reported after delivery).
alter table order_items
  add column refunded_cents integer not null default 0,
  add column refund_note text,
  add column refunded_at timestamptz;
-- Running total of item refunds on the order, so re-saving the receipt total doesn't try to charge them back.
alter table orders add column item_refunds_cents integer not null default 0;

-- 2) Which database this is. "live" = real customers. The separate test database is set to "test"
--    (supabase/test-database-setup.sql does that), and the app refuses test-mode Stripe checkouts on "live".
alter table settings add column environment text not null default 'live' check (environment in ('live', 'test'));

-- 3) Data API access for every table.
--    Supabase stopped granting this automatically for tables created after Oct 30, 2026, so a NEW project
--    (like a separate test database) built from these migrations would otherwise answer "permission denied".
--    On a project that already has these grants this changes nothing. Row Level Security still decides
--    which rows each person can see.
grant usage on schema public to anon, authenticated, service_role;
grant all on all tables in schema public to anon, authenticated, service_role;
grant all on all sequences in schema public to anon, authenticated, service_role;
grant all on all functions in schema public to anon, authenticated, service_role;
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema public grant all on functions to anon, authenticated, service_role;

-- 4) Re-apply the profile lockdown from 0015 (the grant above would otherwise undo it):
--    customers may only change their own name, phone and "seen the fees" flag.
revoke insert, update, delete on profiles from anon, authenticated;
grant update (full_name, phone, fees_seen_at) on profiles to authenticated;

-- ════════════ 0017_kroger_card.sql ════════════
-- Kroger card (Alt ID) phone number: customers can give the number on their Kroger card so their order is rung
-- up with it (their clipped digital coupons apply, they get the fuel points). Blank = Cody uses his own card.
alter table profiles add column kroger_card_phone text;  -- remembered for next time
alter table orders add column kroger_card_phone text;    -- what to use for this order

-- Customers may change their own Kroger card number too (still not role or Stripe id).
grant update (full_name, phone, fees_seen_at, kroger_card_phone) on profiles to authenticated;

-- ════════════ mark this database as TEST ════════════
update settings set environment = 'test';
